329	// ── Verifying (§3.78, phase B3) ──────────────────────────────────────────────
330	//
331	// A written file is not a fixed one. The rule that was faulted is still in the
332	// result on screen, because that result was measured before the edit — and the
333	// whole discipline §3.2 set for base images is that a fix is judged by a
334	// re-scan, never by the confidence of whatever produced it. So the write starts
335	// one, and the verdict it reports is binary: the rule is gone, or it is not.
336	//
337	// The scan is an ordinary job (§3.58), which is what makes starting it on the
338	// user's behalf acceptable: it shows up in `:jobs` with a label saying why, and
339	// `K` stops it. Nothing is hidden and nothing is unstoppable.
340	
341	// misconfigVerify is the fix waiting on a re-scan to say whether it worked.
342	type misconfigVerify struct {
343		Target string
344		Rule   string
345		// File is the file the finding points at, where the rule is looked for.
346		File     string
347		Instance string
348		// Scope is what a rule that clears a whole workload is looked for in
349		// (DEVDESK-688). The zero value: this occurrence, through holdsRule.
350		Scope remediation.Scope
351	}
352	
353	// MisconfigVerifiedMsg is the verdict: whether the rule the fix was about is
354	// still reported for that file.
355	type MisconfigVerifiedMsg struct {
356		Target  string
357		Rule    string
358		File    string
359		Cleared bool
360		// Scope is the scope the verdict was judged by; the zero value for a fix of
361		// one occurrence.
362		Scope remediation.Scope
363		// Still lists the rule ids the re-scan still reports in the scope of the
364		// fix; Cleared is true when it is empty (DEVDESK-688).
365		Still []string
366		// Result is the scan the verdict was read from, so the tab can stop showing
367		// findings the edit has already dealt with.
368		Result *scan.Result
369		Err    error
370	}
371	
372	// startMisconfigVerification re-scans the target the fix was written into.
373	//
374	// It runs even when the catalog is sure of itself, because being sure is not
375	// the same as having measured — and the cases where a rule survives its own fix
376	// are exactly the ones nobody predicted.
377	func (m Model) startMisconfigVerification(v misconfigVerify) tea.Cmd {
378		if m.scanningTarget(v.Target) {
379			// Something is already measuring this target; its result will answer.
380			return nil
381		}
382		job := inventoryScanJob{Kind: kindRepo, Name: v.Target}
383		opts := m.scanOptions()
384		return jobs.StartInContext(
385			jobs.NewRun(jobs.KindScan, command.ViewSecurity, "", "verify fix", v.Target),
386			func(contextName string) tea.Cmd {
387				return rescanCmd([]inventoryScanJob{job}, opts, contextName)
388			},
389		)
390	}
391	
392	// verifyMisconfigCmd reads the result the re-scan stored and answers whether the
393	// rule is still there. It runs off Update (Rule 110).
394	func verifyMisconfigCmd(v misconfigVerify) tea.Cmd {
395		return func() tea.Msg {
396			result, err := cache.ReadWorkspaceScanResult(v.Target)
397			if err != nil {
398				return MisconfigVerifiedMsg{Target: v.Target, Rule: v.Rule, File: v.File, Err: err}
399			}
400			still := stillReported(result, v)
401			return MisconfigVerifiedMsg{
402				Target: v.Target, Rule: v.Rule, File: v.File,
403				Cleared: len(still) == 0, Still: still, Scope: v.Scope, Result: result,
404			}
405		}
406	}
407	
408	// stillReported lists the rule ids the result still reports for the fix v.
409	//
410	// Without a scope it is holdsRule on the occurrence that was fixed. With one, it
411	// is each rule of the scope looked for in the lines of the edited workload: one
412	// edit cleared them for every container of the pod, so a finding on another
413	// container still counts, and a finding of another workload of the file does not.
414	// A scope with no lines (0, 0: the computation failed) reads the whole file, the
415	// safe side: "still reported" at worst, never a "fixed" that was not measured.
416	func stillReported(result *scan.Result, v misconfigVerify) []string {
417		if len(v.Scope.Rules) == 0 {
418			if holdsRule(result, v.Rule, v.File, v.Instance) {
419				return []string{v.Rule}
420			}
421			return nil
422		}
423		if result == nil {
424			return nil
425		}
426		var still []string
427		for _, rule := range v.Scope.Rules {
428			if holdsRuleInScope(result, rule, v.File, v.Scope) {
429				still = append(still, rule)
430			}
431		}
432		return still
433	}
434	
435	// holdsRuleInScope says whether the result reports rule in file, at a line that
436	// is inside the scope's lines (anywhere in the file when the scope has none). A
437	// finding with no line (Line <= 0) cannot be placed outside the scope, so it
438	// counts as inside: the safe side.
439	func holdsRuleInScope(result *scan.Result, rule, file string, scope remediation.Scope) bool {
440		want := remediation.RuleKey(rule)
441		wholeFile := scope.Line == 0 && scope.EndLine == 0
442		for _, f := range result.Findings {
443			if scan.Categorize(f) != scan.CategoryMisconfiguration || f.File != file || remediation.RuleKey(f.ID) != want {
444				continue
445			}
446			if wholeFile || f.Line <= 0 || (f.Line >= scope.Line && f.Line <= scope.EndLine) {
447				return true
448			}
449		}
450		return false
451	}
452	
453	// holdsRule says whether a result still reports this rule for this file —
454	// and, when instance is set, this occurrence of it.
455	//
456	// It matches through remediation.RuleKey rather than on the string, for the
457	// reason the catalog does: Trivy spells one rule two ways, and a comparison
458	// that missed the other spelling would report every fix as successful.
459	//
460	// The occurrence matters for a manifest (§3.80): a Deployment with two
461	// containers is flagged for KSV-0001 twice in one file, and the fix edits one
462	// of them. Judged on the rule and the file alone, the untouched container
463	// would read as the fix having failed.
464	func holdsRule(result *scan.Result, rule, file, instance string) bool {
465		if result == nil {
466			return false
467		}
468		want := remediation.RuleKey(rule)
469		for _, f := range result.Findings {
470			if scan.Categorize(f) != scan.CategoryMisconfiguration {
471				continue
472			}
473			if f.File == file && remediation.RuleKey(f.ID) == want && (instance == "" || instanceOf(f) == instance) {
474				return true
475			}
476		}
477		return false
478	}
479	
480	// instanceOf identifies one occurrence of a rule in a file, without its line,
481	// which the fix itself moves. Trivy words the occurrence in Message ("Container
482	// 'api' of Deployment 'web' should set…"), kubeconform in Title
483	// ("Deployment/web: …"); the pair covers both.
484	func instanceOf(f scan.Finding) string {
485		return f.Title + "\n" + f.Message
486	}
487	
488	// handleMisconfigVerified reports the verdict, and swaps in the result it was
489	// read from.
490	//
491	// The swap is what keeps the screen from contradicting the footer: without it a
492	// line saying the rule is gone would sit above a table still listing it.
493	func (m Model) handleMisconfigVerified(msg MisconfigVerifiedMsg) (tea.Model, tea.Cmd) {
494		if msg.Target != m.targetPath {
495			return m, nil
496		}
497		m.misconfigVerifying = nil
498		if msg.Err != nil {
499			log.Printf("ERROR [security/misconfig] verify %s: %v", msg.Rule, msg.Err)
500			return m, m.footer.Error("Could not read the verification scan — check logs")
501		}
502		if msg.Result != nil {
503			m.setResult(msg.Result)
504		}
505		if !msg.Cleared {
506			// Not a failure: the file was written, and the rule still fires. Saying
507			// so is the only honest answer, and it is why the scan exists.
508			ids := msg.Still
509			if len(ids) == 0 {
510				ids = []string{msg.Rule}
511			}
512			return m, m.footer.Warn(fmt.Sprintf("%s still reported in %s after the fix", strings.Join(ids, " and "), msg.File))
513		}
514		if len(msg.Scope.Rules) > 0 {
515			return m, m.footer.Info(fmt.Sprintf("%s cleared for the whole pod in %s — confirmed by a re-scan",
516				strings.Join(msg.Scope.Rules, " and "), msg.File))
517		}
518		return m, m.footer.Info(fmt.Sprintf("%s cleared in %s — confirmed by a re-scan", msg.Rule, msg.File))
519	}
